import java.util.*;
import java.io.*;

public class Main {
    static int n, k, mod;
    static int[] factorial = new int[262155];
    static int[] invFactorial = new int[262155];
    static int[] logArr = new int[262155];
    static int[] count2 = new int[262155];
    static int[][] dp = new int[262155][31];
    static boolean[][] visited = new boolean[262155][31];
    static List<int[]> history = new ArrayList<>();
    static Queue<int[]> q = new LinkedList<>();

    static int inputInt(BufferedReader br) throws IOException {
        return Integer.parseInt(br.readLine());
    }

    static int countDiv2(int x) {
        int count = 0;
        while (x != 0 && (x & 1) == 0) {
            ++count;
            x >>= 1;
        }
        return count;
    }

    static int fastPow(int base, long exp) {
        int result = 1;
        long b = base;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (int)((long)result * b % mod);
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    }

    static int choose(int n, int m) {
        return (int)((long)factorial[n] * invFactorial[m] % mod * invFactorial[n - m] % mod);
    }

    static int recurse(int n, int k) {
        if (n == 0) return 1;
        if (k == 0) return 0;
        if (dp[n][k] != -1) return dp[n][k];
        int res = 0;
        int limit = 1 << logArr[n];
        for (int i = n; i >= limit; i -= 2) {
            res = (res + (long)choose(n, i) * recurse(n - i, k - 1) % mod * k) % mod;
        }
        return dp[n][k] = res;
    }

    static int performBFS(int n, int k) {
        q.clear();
        q.add(new int[]{n, k});
        while (!q.isEmpty()) {
            int[] front = q.poll();
            int x = front[0], y = front[1];
            history.add(new int[]{x, y});
            if (x == 0 || y == 0) continue;
            int limit = 1 << logArr[x];
            for (int i = x; i >= limit; i -= 2) {
                if (count2[i] + count2[x - i] == count2[x] && !visited[i][y - 1]) {
                    visited[i][y - 1] = true;
                    q.add(new int[]{i, y - 1});
                }
            }
        }
        int[] resArr = new int[history.size()];
        for (int i = history.size() - 1; i >= 0; --i) {
            int x = history.get(i)[0], y = history.get(i)[1];
            if (x == 0) {
                dp[x][y] = 1;
                continue;
            }
            if (y == 0) {
                dp[x][y] = 0;
                continue;
            }
            int limit = 1 << logArr[x];
            int sum = 0;
            for (int i = x; i >= limit; i -= 2) {
                if (count2[i] + count2[x - i] == count2[x]) {
                    sum = (sum + (long)choose(x, i) * dp[x - i][y - 1] % mod * y) % mod;
                }
            }
            dp[x][y] = sum;
        }
        return dp[n][k];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        for (int i = 0; i < 262155; i++) {
            Arrays.fill(dp[i], -1);
        }
        for (int i = 0; i < 262155; i++) {
            Arrays.fill(visited[i], false);
        }

        factorial[0] = 1;
        logArr[0] = -1;
        for (int i = 1; i <= 262150; i++) {
            factorial[i] = (int)((long)factorial[i - 1] * i % mod);
            logArr[i] = logArr[i >> 1] + 1;
            count2[i] = count2[i - 1] + countDiv2(i);
        }

        invFactorial[262150] = fastPow(factorial[262150], mod - 2);
        for (int i = 262149; i > 0; i--) {
            invFactorial[i] = (int)((long)invFactorial[i + 1] * (i + 1) % mod);
        }
        invFactorial[0] = invFactorial[1];

        if ((n & 1) == 1) {
            System.out.println(fastPow(k, n));
        } else {
            int cnt = 0;
            for (int i = 0; i < 62; i++) {
                if (((long)n & (1L << i)) != 0) cnt++;
            }
            int ans = fastPow(k, n);
            int bfsResult = performBFS(n, k);
            int result = ((ans - bfsResult) % mod + mod) % mod;
            System.out.println(result);
        }
    }
}
